    /**
     * The product's own tab with that English title, by the product's slug;
     * nothing when the shop has no such product or tab.
     *
     * @return list<array{0: object, 1: string, 2: string}>
     */
    private function tabs(): array
    {
        if (! Schema::hasTable('product_tabs')) {
            return [];
        }

        $out = [];
        $ids = DB::table('products')->whereIn('slug', array_keys(self::TABS))->pluck('id', 'slug');

        foreach (self::TABS as $slug => $rows) {
            if (! isset($ids[$slug])) {
                continue;
            }
            foreach ($rows as [$english, $title, $body]) {
                $tab = DB::table('product_tabs')->where('product_id', $ids[$slug])->where('title', $english)->orderBy('id')->first(['id', 'title', 'body']);
                if ($tab !== null) {
                    $out[] = [$tab, $title, $body];
                }
            }
        }

        return $out;
    }

    private function put(string $group, int $id, string $field, string $value, string $english): bool
    {
        $key = ['locale' => 'ar', 'group' => $group, 'item_id' => $id, 'field' => $field];
        $row = DB::table('translations')->where($key)->first(['id', 'status', 'value']);

        if ($row !== null && $row->status === 'published' && trim((string) $row->value) !== '') {
            return false;
        }

        $data = ['value' => $value, 'status' => 'published', 'source' => 'manual', 'source_hash' => sha1($english),
            'reviewed_at' => now(), 'updated_at' => now()];

        $row === null
            ? DB::table('translations')->insert($key + $data + ['created_at' => now()])
            : DB::table('translations')->where('id', $row->id)->update($data);

        return true;
    }
};
